    /// 점이 공개 어장 자료의 좌표 범위 안에 있으면 그 기록을 돌려줍니다.
    static func matches(latitude: Double, longitude: Double) -> [LicensedGround] {
        grounds.filter {
            latitude >= $0.minLat && latitude <= $0.maxLat
                && longitude >= $0.minLon && longitude <= $0.maxLon
        }
    }
